package vn.cinema.security;
import org.springframework.web.filter.OncePerRequestFilter;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;
public class InternalFilter extends OncePerRequestFilter{private final byte[] key;public InternalFilter(String key){this.key=key.getBytes(StandardCharsets.UTF_8);}
 protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{if(req.getRequestURI().startsWith("/internal/")){var value=req.getHeader("X-Internal-Key");if(value==null||!MessageDigest.isEqual(key,value.getBytes(StandardCharsets.UTF_8))){SecurityConfig.fail(res,403,"Không có quyền truy cập nội bộ");return;}SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("internal",null,java.util.List.of(new SimpleGrantedAuthority("ROLE_INTERNAL"))));}chain.doFilter(req,res);}}